#!/usr/bin/env python3
"""Network golden rows for tests/golden/expected.yaml (owner M2), written from the specification.

    .venv/bin/python tests/fixtures/pcap/gen_golden_rows.py            # print the section
    .venv/bin/python tests/fixtures/pcap/gen_golden_rows.py --write    # replace it in expected.yaml

Independence rules (docs/GOLDEN.md, M1 request):

* Observations come from ``tshark -T json`` read here; no scanner code is imported, so the rows cannot
  be copied from the output under test.
* Decomposition follows docs/PLAN.md 7.3 (``TLS_<KX>_<AU>_WITH_<CIPHER>_<MAC>``, TLS 1.3 cipher plus
  hash, signature schemes, SSH names) and the SSH rules of 7.1. Names come from the IANA snapshots in
  src/quantumtrace/kb/iana (IANA data), never from the engine.
* Tiers and flags come from PLAN 7.1 and M1M2-04 only. Canonical spellings are the KB ids of
  PLAN 7.2 with ``<family>-<bits>`` for sized RSA, DH and AES, as docs/GOLDEN.md allows.
* A combination the starter kit does not exercise raises instead of being guessed.

Spec ambiguities, written into the output as comments (not silently resolved):

* TLS 1.3 suite hash: PLAN 7.3 says "SHA-256 (hash/HKDF)". Rows use HKDF, usage kdf, one per session
  whatever the hash (engine README, RFC 8446 section 7.1).
* Hash of a signature scheme or SSH host key: PLAN 7.1 says "RSA + SHA-1 signature" for ssh-rsa, so the
  hash component of a signature carries usage ``signature``.
* Hash of an SSH key exchange name (``diffie-hellman-group14-sha1``): usage ``hash``.
"""

from __future__ import annotations

import csv
import json
import re
import subprocess
import sys
from collections import Counter, defaultdict
from dataclasses import dataclass
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[3]
KIT = ROOT / "network-capture" / "network.pcap"
SOURCE = "network-capture/network.pcap"
IANA = ROOT / "src" / "quantumtrace" / "kb" / "iana"
GOLDEN = ROOT / "tests" / "golden" / "expected.yaml"
BEGIN = "# --- network section (owner M2) begin: generated by tests/fixtures/pcap/gen_golden_rows.py ---"
END = "# --- network section (owner M2) end ---"

PRECEDENCE = {"CRITICAL": 3, "MEDIUM": 2, "UNKNOWN": 1, "SAFE": 0}
_GREASE = re.compile(r"^0x([0-9a-f])a\1a$", re.I)
_SIGNALLING_SUITES = {0x00FF, 0x5600}


# --- observations: tshark -T json, extraction code of its own -----------------------------------------


def _tshark(flt: str, fields: list[str]) -> list[dict[str, list[str]]]:
    cmd = ["tshark", "-n", "-r", str(KIT), "--enable-heuristic", "tls_tcp", "-Y", flt, "-T", "json"]
    for field in fields:
        cmd += ["-e", field]
    out = subprocess.run(cmd, capture_output=True, text=True, check=True).stdout
    rows = []
    for packet in json.loads(out or "[]"):
        layers = packet["_source"]["layers"]
        rows.append({k: v if isinstance(v, list) else [v] for k, v in layers.items()})
    return rows


def _num(text: str) -> int:
    return int(text, 16) if text.lower().startswith("0x") else int(text)


def _clean(values: list[str], *, suites: bool = False) -> list[int]:
    out = []
    for value in values:
        number = _num(value)
        if _GREASE.match(f"0x{number:04x}") or (suites and number in _SIGNALLING_SUITES):
            continue
        out.append(number)
    return list(dict.fromkeys(out))


def tls_sessions() -> list[dict[str, Any]]:
    fields = [
        "tcp.stream",
        "ip.src",
        "tcp.srcport",
        "ip.dst",
        "tcp.dstport",
        "tls.handshake.type",
        "tls.handshake.extensions_server_name",
        "tls.handshake.ciphersuite",
        "tls.handshake.extensions_supported_group",
        "tls.handshake.extensions_key_share_group",
        "tls.handshake.sig_hash_alg",
        "tls.handshake.extensions.supported_version",
        "tls.handshake.version",
    ]
    streams: dict[str, dict[str, Any]] = {}
    for row in _tshark("tls.handshake.type==1 or tls.handshake.type==2", fields):
        kind = _num(row["tls.handshake.type"][0])
        stream = streams.setdefault(row["tcp.stream"][0], {})
        if kind == 1 and "ch" not in stream:
            stream["ch"] = row
            stream["flow"] = (
                f"{row['ip.src'][0]}:{row['tcp.srcport'][0]}->{row['ip.dst'][0]}:{row['tcp.dstport'][0]}"
            )
        if kind == 2 and "sh" not in stream:
            stream["sh"] = row
    sessions = []
    for number in sorted(streams, key=int):
        stream = streams[number]
        if "ch" not in stream or "sh" not in stream:
            raise ValueError(f"stream {number} lacks a ClientHello or a ServerHello")
        ch, sh = stream["ch"], stream["sh"]
        versions = _clean(sh.get("tls.handshake.extensions.supported_version", []))
        version = versions[0] if versions else _num(sh["tls.handshake.version"][0])
        shares = sh.get("tls.handshake.extensions_key_share_group", [])
        sessions.append(
            {
                "stream": int(number),
                "flow": stream["flow"],
                "sni": (ch.get("tls.handshake.extensions_server_name") or [None])[0],
                "version": version,
                "offered_suites": _clean(ch["tls.handshake.ciphersuite"], suites=True),
                "negotiated_suite": _num(sh["tls.handshake.ciphersuite"][0]),
                "offered_groups": _clean(ch.get("tls.handshake.extensions_supported_group", [])),
                "negotiated_group": _num(shares[0]) if shares else None,
                "offered_sigs": _clean(ch.get("tls.handshake.sig_hash_alg", [])),
            }
        )
    return sessions


def ssh_sessions() -> list[dict[str, Any]]:
    fields = [
        "tcp.stream",
        "ip.src",
        "tcp.srcport",
        "ip.dst",
        "tcp.dstport",
        "ssh.kex_algorithms",
        "ssh.server_host_key_algorithms",
        "ssh.encryption_algorithms_client_to_server",
        "ssh.encryption_algorithms_server_to_client",
        "ssh.mac_algorithms_client_to_server",
        "ssh.mac_algorithms_server_to_client",
    ]
    streams: dict[str, dict[str, Any]] = defaultdict(dict)
    for row in _tshark("ssh.message_code == 20", fields):
        role = "server" if row["tcp.srcport"][0] == "22" else "client"
        lists = {}
        for key in fields[6:]:
            cell = row.get(key, [])
            lists[key] = cell[0].split(",") if len(cell) == 1 else cell
        lists["kex"] = (row.get("ssh.kex_algorithms") or [""])[0].split(",")
        client_flow = (
            f"{row['ip.src'][0]}:{row['tcp.srcport'][0]}->{row['ip.dst'][0]}:{row['tcp.dstport'][0]}"
            if role == "client"
            else f"{row['ip.dst'][0]}:{row['tcp.dstport'][0]}->{row['ip.src'][0]}:{row['tcp.srcport'][0]}"
        )
        streams[row["tcp.stream"][0]][role] = lists
        streams[row["tcp.stream"][0]]["flow"] = client_flow
    out = []
    for number in sorted(streams, key=int):
        s = streams[number]
        if "client" not in s or "server" not in s:
            raise ValueError(f"SSH stream {number} lacks a client or a server KEXINIT")
        out.append({"stream": int(number), "flow": s["flow"], "client": s["client"], "server": s["server"]})
    return out


def http_flows() -> list[dict[str, Any]]:
    fields = [
        "tcp.stream",
        "ip.src",
        "tcp.srcport",
        "ip.dst",
        "tcp.dstport",
        "http.request.method",
        "http.request.uri",
        "http.host",
        "http.response.code",
        "http.server",
    ]
    streams: dict[str, dict[str, Any]] = {}
    for row in _tshark("http", fields):
        s = streams.setdefault(row["tcp.stream"][0], {})
        if row.get("http.request.method") and "method" not in s:
            s["method"] = row["http.request.method"][0]
            s["path"] = row["http.request.uri"][0]
            s["host"] = (row.get("http.host") or [None])[0]
            s["flow"] = (
                f"{row['ip.src'][0]}:{row['tcp.srcport'][0]}->{row['ip.dst'][0]}:{row['tcp.dstport'][0]}"
            )
        if row.get("http.response.code") and "status" not in s:
            s["status"] = int(row["http.response.code"][0])
            s["server"] = (row.get("http.server") or [None])[0]
    return [dict(stream=int(k), **v) for k, v in sorted(streams.items(), key=lambda kv: int(kv[0]))]


# --- IANA names ---------------------------------------------------------------------------------------


def _iana_suites() -> dict[int, str]:
    out = {}
    with (IANA / "tls-cipher-suites.csv").open(newline="") as handle:
        for row in csv.DictReader(handle):
            match = re.fullmatch(r"0x([0-9A-Fa-f]{2}),0x([0-9A-Fa-f]{2})", row["Value"])
            if match:
                out[int(match[1] + match[2], 16)] = row["Description"]
    return out


def _iana_groups() -> dict[int, str]:
    out = {}
    with (IANA / "tls-supported-groups.csv").open(newline="") as handle:
        for row in csv.DictReader(handle):
            if row["Value"].isdigit():
                out[int(row["Value"])] = row["Description"]
    return out


def _iana_sigs() -> dict[int, str]:
    out = {}
    with (IANA / "tls-signature-schemes.csv").open(newline="") as handle:
        for row in csv.DictReader(handle):
            if re.fullmatch(r"0x[0-9A-Fa-f]{4}", row["Value"]):
                out[int(row["Value"], 16)] = row["Description"]
    return out


SUITES, GROUPS, SIGS = _iana_suites(), _iana_groups(), _iana_sigs()


# --- decomposition (PLAN 7.3) and policy (PLAN 7.1) ---------------------------------------------------


@dataclass(frozen=True)
class Component:
    canonical: str
    usage: str
    curve: str | None = None
    mode: str | None = None

    @property
    def identity(self) -> tuple[Any, ...]:
        return (self.canonical, self.usage, self.curve, self.mode)


def policy(c: Component) -> tuple[str, bool, bool]:
    """-> (tier, classically_broken, hndl_exposed), from PLAN 7.1 and M1M2-04."""
    name, usage = c.canonical, c.usage
    broken = False
    if name in {"RSA", "ECDH", "X25519", "ECDSA", "Ed25519"} or name.startswith(("RSA-", "DH")):
        tier = "CRITICAL"
        broken = name in {"DH-1024"} or name.startswith("RSA-") and int(name.split("-")[1]) < 2048
    elif name == "X25519MLKEM768":
        tier = "SAFE"
    elif name in {"AES-128"}:
        tier = "MEDIUM"
    elif name in {"AES-256", "ChaCha20-Poly1305"}:
        tier = "SAFE"
    elif name == "3DES":
        tier, broken = "MEDIUM", True
    elif name == "SHA-1":
        tier, broken = "MEDIUM", True  # PLAN 7.1: SHA-1 (hash, in signatures); D.3 lists it as broken
    elif name == "HMAC-SHA1":
        tier = "MEDIUM"  # M1M2-04: MAC SHA-1 is distinct from a collision-broken SHA-1 signature
    elif name in {"SHA-256", "SHA-384", "SHA-512", "HMAC-SHA256", "HKDF"}:
        tier = "SAFE"
    else:
        raise ValueError(f"no policy row for {name}")
    hndl = usage == "key_exchange" and tier == "CRITICAL"  # PLAN 7.1: Shor-vulnerable KEX in transit
    return tier, broken, hndl


_HMAC = {"SHA": "HMAC-SHA1", "SHA256": "HMAC-SHA256", "SHA384": "HMAC-SHA384"}  # KB ids
_HASH = {"SHA": "SHA-1", "SHA1": "SHA-1", "SHA256": "SHA-256", "SHA384": "SHA-384", "SHA512": "SHA-512"}


def _cipher(token: str) -> Component:
    match = re.fullmatch(r"AES_(128|256)_(CBC|GCM)", token)
    if match:
        return Component(f"AES-{match[1]}", "encryption", mode=match[2].lower())
    if token == "3DES_EDE_CBC":
        return Component("3DES", "encryption", mode="cbc")
    if token == "CHACHA20_POLY1305":
        return Component("ChaCha20-Poly1305", "encryption")
    raise ValueError(f"cipher {token} is not exercised by the starter kit")


def suite_components(code: int) -> list[Component]:
    """PLAN 7.3: TLS <= 1.2 KX/AU/CIPHER/MAC, TLS 1.3 CIPHER + HKDF."""
    name = SUITES[code]
    match = re.fullmatch(r"TLS_RSA_WITH_(?P<cipher>.+)_(?P<mac>SHA|SHA256|SHA384)", name)
    if match and match["cipher"].endswith("CBC"):  # static RSA: key transport + authentication
        return [
            Component("RSA", "key_exchange"),
            Component("RSA", "authentication"),
            _cipher(match["cipher"]),
            Component(_HMAC[match["mac"]], "mac"),
        ]
    match = re.fullmatch(
        r"TLS_(?P<cipher>AES_(?:128|256)_GCM|CHACHA20_POLY1305)_(?P<hash>SHA256|SHA384)", name
    )
    if match:  # TLS 1.3: key exchange comes from the group, not the suite
        return [_cipher(match["cipher"]), Component("HKDF", "kdf")]
    raise ValueError(f"suite {name} is not exercised by the starter kit")


def group_components(code: int) -> list[Component]:
    name = GROUPS.get(code) or f"unassigned {code}"
    if name == "x25519":
        return [Component("X25519", "key_exchange")]
    if name == "secp256r1":
        return [Component("ECDH", "key_exchange", curve="secp256r1")]
    if name == "X25519MLKEM768":
        return [Component("X25519MLKEM768", "key_exchange")]  # hybrid trace halves are not separate rows
    raise ValueError(f"group {name} is not exercised by the starter kit")


def sig_components(code: int) -> list[Component]:
    name = SIGS.get(code) or f"unassigned {code}"
    match = re.fullmatch(r"rsa_(?:pkcs1|pss_rsae|pss_pss)_(sha256|sha384|sha512)", name)
    if match:
        return [Component("RSA", "signature"), Component(_HASH[match[1].upper()], "signature")]
    match = re.fullmatch(r"ecdsa_(secp256r1)_(sha256)", name)
    if match:
        return [
            Component("ECDSA", "signature", curve=match[1]),
            Component(_HASH[match[2].upper()], "signature"),
        ]
    if name == "ed25519":
        return [Component("Ed25519", "signature")]
    raise ValueError(f"signature scheme {name} is not exercised by the starter kit")


SSH_KEX = {  # PLAN 7.1 SSH rules; M1M2-04 for the names
    "diffie-hellman-group1-sha1": [Component("DH-1024", "key_exchange"), Component("SHA-1", "hash")],
    "diffie-hellman-group14-sha1": [Component("DH-2048", "key_exchange"), Component("SHA-1", "hash")],
    "diffie-hellman-group16-sha512": [Component("DH-4096", "key_exchange"), Component("SHA-512", "hash")],
    "curve25519-sha256": [Component("X25519", "key_exchange"), Component("SHA-256", "hash")],
}
SSH_HOST_KEY = {
    "ssh-rsa": [Component("RSA", "signature"), Component("SHA-1", "signature")],
    "rsa-sha2-512": [Component("RSA", "signature"), Component("SHA-512", "signature")],
    "ssh-ed25519": [Component("Ed25519", "signature")],
}
SSH_CIPHER = {
    "3des-cbc": [Component("3DES", "encryption", mode="cbc")],
    "aes128-cbc": [Component("AES-128", "encryption", mode="cbc")],
    "aes256-gcm@openssh.com": [Component("AES-256", "encryption", mode="gcm")],
    "chacha20-poly1305@openssh.com": [Component("ChaCha20-Poly1305", "encryption")],
}
SSH_MAC = {
    "hmac-sha1": [Component("HMAC-SHA1", "mac")],
    "hmac-sha2-256-etm@openssh.com": [Component("HMAC-SHA256", "mac")],
}
SIGNALLING_KEX = {"ext-info-c", "ext-info-s", "kex-strict-c-v00@openssh.com", "kex-strict-s-v00@openssh.com"}
SSH_AEAD = {"chacha20-poly1305@openssh.com", "aes128-gcm@openssh.com", "aes256-gcm@openssh.com"}


def _first_match(client: list[str], server: list[str]) -> str | None:
    listed = set(server)
    return next((x for x in client if x in listed), None)  # RFC 4253 section 7.1


# --- rows -----------------------------------------------------------------------------------------------


Occurrence = dict[tuple[Any, ...], dict[str, Any]]


def _add(table: Occurrence, components: list[Component], negotiated: bool) -> None:
    for c in components:
        entry = table.setdefault(c.identity, {"component": c, "negotiated": False})
        entry["negotiated"] = entry["negotiated"] or negotiated


def tls_occurrences(s: dict[str, Any]) -> Occurrence:
    table: Occurrence = {}
    for code in s["offered_suites"]:
        _add(table, suite_components(code), code == s["negotiated_suite"])
    if s["negotiated_suite"] not in s["offered_suites"]:
        raise ValueError(f"stream {s['stream']}: negotiated suite was not offered")
    for code in s["offered_groups"]:
        _add(table, group_components(code), code == s["negotiated_group"])
    for code in s["offered_sigs"]:
        _add(table, sig_components(code), False)  # TLS 1.2 RSA transport and TLS 1.3 select none visibly
    return table


def ssh_occurrences(s: dict[str, Any]) -> Occurrence:
    c, srv = s["client"], s["server"]
    table: Occurrence = {}
    kex_sel = _first_match(
        [x for x in c["kex"] if x not in SIGNALLING_KEX], [x for x in srv["kex"] if x not in SIGNALLING_KEX]
    )
    host_sel = _first_match(c["ssh.server_host_key_algorithms"], srv["ssh.server_host_key_algorithms"])
    enc_sel = _first_match(
        c["ssh.encryption_algorithms_client_to_server"], srv["ssh.encryption_algorithms_client_to_server"]
    )
    mac_sel = (
        None
        if enc_sel in SSH_AEAD  # an AEAD cipher carries its own authentication (M1M2-06)
        else _first_match(
            c["ssh.mac_algorithms_client_to_server"], srv["ssh.mac_algorithms_client_to_server"]
        )
    )
    for name in c["kex"]:
        if name in SIGNALLING_KEX:  # capability markers, not algorithms (RFC 8308, OpenSSH strict kex)
            continue
        _add(table, SSH_KEX[name], name == kex_sel)
    for name in c["ssh.server_host_key_algorithms"]:
        _add(table, SSH_HOST_KEY[name], name == host_sel)
    for name in dict.fromkeys(
        c["ssh.encryption_algorithms_client_to_server"] + c["ssh.encryption_algorithms_server_to_client"]
    ):
        _add(table, SSH_CIPHER[name], name == enc_sel)
    for name in dict.fromkeys(
        c["ssh.mac_algorithms_client_to_server"] + c["ssh.mac_algorithms_server_to_client"]
    ):
        _add(table, SSH_MAC[name], name == mac_sel)
    s["selected"] = {"kex": kex_sel, "host_key": host_sel, "cipher": enc_sel, "mac": mac_sel}
    return table


def _asset_row(entry: dict[str, Any], source_type: str) -> dict[str, Any]:
    c: Component = entry["component"]
    tier, broken, hndl = policy(c)
    return {
        "kind": "asset",
        "source": SOURCE,
        "source_type": source_type,
        "canonical": c.canonical,
        "usage": c.usage,
        "tier": tier,
        "classically_broken": broken,
        "hndl_exposed": hndl,
        "negotiated": entry["negotiated"],
    }


def _session_tier(table: Occurrence) -> tuple[str, str | None]:
    """-> (tier_session, tier_kex). PLAN 7.1: CRITICAL > MEDIUM > UNKNOWN > SAFE over the negotiated
    components; the certificate is never in a TLS 1.3 or kit TLS 1.2 capture, so authentication is
    unobservable and contributes UNKNOWN."""
    tiers = [policy(e["component"])[0] for e in table.values() if e["negotiated"]]
    kex = [
        policy(e["component"])[0]
        for e in table.values()
        if e["negotiated"] and e["component"].usage == "key_exchange"
    ]
    tiers.append("UNKNOWN")
    return max(tiers, key=PRECEDENCE.__getitem__), (kex[0] if len(set(kex)) == 1 else None)


def build() -> dict[str, list[dict[str, Any]]]:
    tls, ssh, http = tls_sessions(), ssh_sessions(), http_flows()
    snis = Counter(s["sni"] for s in tls)
    out: dict[str, list[dict[str, Any]]] = {"asset": [], "session": [], "count": [], "finding": []}
    for s in tls:
        table = tls_occurrences(s)
        label = {0x0303: "TLS 1.2", 0x0304: "TLS 1.3"}[s["version"]]
        header = f"stream {s['stream']} {label} sni={s['sni']} suite={SUITES[s['negotiated_suite']]}"
        for entry in table.values():
            row = _asset_row(entry, "pcap")
            row["_comment"] = header
            header = ""
            out["asset"].append(row)
        tier_session, tier_kex = _session_tier(table)
        if snis[s["sni"]] == 1:
            group = GROUPS[s["negotiated_group"]] if s["negotiated_group"] is not None else None
            out["session"].append(
                {
                    "kind": "session",
                    "source": SOURCE,
                    "source_type": "pcap",
                    "session_sni": s["sni"],
                    "transport": "tls",
                    "negotiated_group": group,
                    "tier_kex": tier_kex,
                    "tier_session": tier_session,
                }
            )
        out["finding"].append(
            {
                "kind": "finding",
                "source": SOURCE,
                "source_type": "pcap",
                "kind_hint": "protocol_version",
                "raw_name": label,
                "extra": {
                    "certificate_state": "encrypted" if s["version"] == 0x0304 else "absent",
                    "authentication_observable": False,  # no Certificate message in the kit (M2M4-02)
                },
            }
        )
    for s in ssh:
        table = ssh_occurrences(s)
        sel = s["selected"]
        header = (
            f"stream {s['stream']} ssh kex={sel['kex']} host_key={sel['host_key']} cipher={sel['cipher']}"
        )
        for entry in table.values():
            row = _asset_row(entry, "ssh")
            row["_comment"] = header
            header = ""
            out["asset"].append(row)
        out["finding"].append(
            {
                "kind": "finding",
                "source": SOURCE,
                "source_type": "ssh",
                "kind_hint": "protocol_version",
                "raw_name": "SSH-2.0",
                # the host key algorithm is selected from both KEXINITs; no host identity is verified
                "extra": {"authentication_observable": sel["host_key"] is not None},
            }
        )
    for h in http:
        out["finding"].append(
            {
                "kind": "finding",
                "source": SOURCE,
                "source_type": "pcap",
                "kind_hint": "plaintext",
                "raw_name": "HTTP",
                "extra": {
                    "hygiene_only": True,
                    "http": {
                        "method": h["method"],
                        "path": h["path"],
                        "server": h["server"],
                        "status": h["status"],
                    },
                },
            }
        )
    out["count"] = [
        {
            "kind": "count",
            "source": SOURCE,
            "source_type": "pcap",
            "metric": "sessions",
            "transport": "tls",
            "count": len(tls),
        },
        {
            "kind": "count",
            "source": SOURCE,
            "source_type": "ssh",
            "metric": "sessions",
            "transport": "ssh",
            "count": len(ssh),
        },
        {
            "kind": "count",
            "source": SOURCE,
            "source_type": "pcap",
            "metric": "occurrences",
            "kind_hint": "plaintext",
            "count": len(http),
        },
    ]
    return out


# --- YAML text --------------------------------------------------------------------------------------------


def _scalar(value: Any) -> str:
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    text = str(value)
    return (
        json.dumps(text)
        if re.search(r"[:#{}\[\],&*!|>'\"%@`]|^\s|\s$|^(null|true|false|yes|no)$", text, re.I)
        else text
    )


def _lines(row: dict[str, Any], indent: str = "") -> list[str]:
    lines = []
    for key, value in row.items():
        if key == "_comment":
            continue
        if isinstance(value, dict):
            lines.append(f"{indent}{key}:")
            lines.extend(_lines(value, indent + "  "))
        else:
            lines.append(f"{indent}{key}: {_scalar(value)}")
    return lines


HEADER = f"""{BEGIN}
# Network golden rows, owner M2 (docs/GOLDEN.md). Source: network-capture/network.pcap.
# Written from PLAN 7.1 (tier rules, SSH rules), PLAN 7.3 (decomposition) and the IANA snapshots in
# src/quantumtrace/kb/iana, from observations read with tshark -T json. Not copied from scanner output.
# Provenance: observations come from tshark only; the built-in parser (purepy.py) was not used. A parsing
# blind spot shared by tshark and the scanner would therefore pass both.
# This section is reproducible from the generator; that is not an accuracy result. Accuracy is measured
# by M1's evaluator (scripts/eval.py), not by the drift test.
# Regenerate: .venv/bin/python tests/fixtures/pcap/gen_golden_rows.py --write (only this block changes)
# One asset row per unique component of one session (the evaluator counts a canonical algorithm/usage once
# per physical site). `negotiated: true` marks components of the negotiated suite/group or of the RFC 4253
# first-match selection; offered-only components carry `negotiated: false`.
# Spec ambiguities, kept explicit:
#  - TLS 1.3 suite hash: PLAN 7.3 says "SHA-256 (hash/HKDF)"; rows use HKDF (kdf), one per session
#    whatever the hash (RFC 8446 section 7.1).
#  - Hash of a signature scheme or of an SSH host key carries usage `signature` (PLAN 7.1: ssh-rsa =
#    RSA + SHA-1 signature); the hash of an SSH kex name carries usage `hash`.
#  - Static RSA key size is not observable (no Certificate), so the canonical name is RSA without a size.
# Finding rows carry no per-host assertion: the evaluator pairs finding rows with occurrences by
# identity fields only, so rows that differ only in `extra` would be assigned arbitrarily.
# Session rows exist only for SNIs that occur once; SSH sessions have no SNI and are covered by asset,
# finding and count rows. No literal session_id (GOLDEN.md).
"""


def render(rows: dict[str, list[dict[str, Any]]]) -> str:
    out = [HEADER.rstrip("\n")]
    for kind in ("count", "session", "finding", "asset"):
        out.append(f"# {kind} rows")
        for row in rows[kind]:
            if row.get("_comment"):
                out.append(f"# {row['_comment']}")
            lines = _lines(row)
            out.append("- " + lines[0])
            out.extend("  " + line for line in lines[1:])
    out.append(END)
    return "\n".join(out) + "\n"


def splice(current: str, section: str) -> str:
    """Replace the text between BEGIN and END, or append the section; every other byte is kept."""
    if BEGIN in current:
        head, rest = current.split(BEGIN, 1)
        tail = rest.split(END, 1)[1] if END in rest else ""
        return head.rstrip("\n") + "\n\n" + section.rstrip("\n") + tail
    return current.rstrip("\n") + "\n\n" + section


def main(argv: list[str]) -> int:
    text = render(build())
    if "--write" not in argv:
        sys.stdout.write(text)
        return 0
    GOLDEN.write_text(splice(GOLDEN.read_text(encoding="utf-8"), text), encoding="utf-8")
    print(f"wrote {GOLDEN.relative_to(ROOT)}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
